  const int tmem_cols = Bpad <= 32 ? 32 : Bpad <= 64 ? 64 : Bpad <= 128 ? 128 : 256;
  const int ebrows = Bpad / 2;
  const int perK = kWBlk + ebrows * 128, avail = kSmemDyn - 1024;
  const int kbs = 2;
  int stages = avail / (kbs * perK);
  if (stages > kMaxStages) stages = kMaxStages;
  CUtensorMap mW, mE;
